CREATE TEMP TABLE _aaemu_base_housing_binding_doodads AS SELECT COALESCE(MAX(id), 0) AS b FROM "housing_binding_doodads";
INSERT INTO "housing_binding_doodads" (id, "owner_id", "owner_type", "attach_point_id", "doodad_id")
SELECT _aaemu_base_housing_binding_doodads.b + n.rowid, n."owner_id", n."owner_type", n."attach_point_id", n."doodad_id" FROM _aaemu_new_housing_binding_doodads n, _aaemu_base_housing_binding_doodads ORDER BY n.rowid;

