INSERT INTO _aaemu_new_localized_texts ("tbl_name", "tbl_column_name", "idx", "ko", "en_us", "zh_cn", "ja", "ru", "zh_tw", "de", "fr")
SELECT v."tbl_name", v."tbl_column_name", v."idx", v."ko", v."en_us", v."zh_cn", v."ja", v."ru", v."zh_tw", v."de", v."fr" FROM v LEFT JOIN "localized_texts" x ON x."tbl_name" = v."tbl_name" AND x."tbl_column_name" = v."tbl_column_name" AND x."idx" = v."idx"
WHERE x."tbl_name" IS NULL;
WITH v("tbl_name", "tbl_column_name", "idx", "ko", "en_us", "zh_cn", "ja", "ru", "zh_tw", "de", "fr") AS (VALUES
('items', 'name', 34983, '마력이 깃든 청사진', 'A magical blueprint', 'A magical blueprint', '', '', '', '', ''),
('items', 'description', 34983, NULL, 'Special materials obtained after decomposing architectural drawings.', 'Special materials obtained after decomposing architectural drawings.', '', '', '', '', ''),
('items', 'name', 37893, '건설용 기둥 묶음', 'Architectural Pillar Pack', 'Architectural Pillar Pack', '', '', '', '', ''),
('items', 'description', 37893, NULL, 'These beams and straight columns are mainly used to improve buildings or change building types.', 'These beams and straight columns are mainly used to improve buildings or change building types.', '', '', '', '', ''),
('items', 'name', 37894, '건설용 공구 묶음', 'construction kit', 'construction kit', '', '', '', '', ''),
('items', 'description', 37894, NULL, 'These metal tools are mainly used to improve buildings or change building types.', 'These metal tools are mainly used to improve buildings or change building types.', '', '', '', '', ''),
