('items', 'description', 37896, NULL, 'These stone bricks are mainly used to improve buildings or change building types.', 'These stone bricks are mainly used to improve buildings or change building types.', '', '', '', '', ''))
INSERT INTO _aaemu_new_localized_texts ("tbl_name", "tbl_column_name", "idx", "ko", "en_us", "zh_cn", "ja", "ru", "zh_tw", "de", "fr")
SELECT v."tbl_name", v."tbl_column_name", v."idx", v."ko", v."en_us", v."zh_cn", v."ja", v."ru", v."zh_tw", v."de", v."fr" FROM v LEFT JOIN "localized_texts" x ON x."tbl_name" = v."tbl_name" AND x."tbl_column_name" = v."tbl_column_name" AND x."idx" = v."idx"
WHERE x."tbl_name" IS NULL;
CREATE TEMP TABLE _aaemu_base_localized_texts AS SELECT COALESCE(MAX(id), 0) AS b FROM "localized_texts";
INSERT INTO "localized_texts" (id, "tbl_name", "tbl_column_name", "idx", "ko", "en_us", "zh_cn", "ja", "ru", "zh_tw", "de", "fr")
SELECT _aaemu_base_localized_texts.b + n.rowid, n."tbl_name", n."tbl_column_name", n."idx", n."ko", n."en_us", n."zh_cn", n."ja", n."ru", n."zh_tw", n."de", n."fr" FROM _aaemu_new_localized_texts n, _aaemu_base_localized_texts ORDER BY n.rowid;

